update INV_StockTransactionHeader set StatusCode = 5 where DocumentTypeID = @DocumentTypeID and DocumentDate between @FromDate and @ToDate and CompanyID = @CompanyID and PeriodID = @PeriodID and FiscalID = @FiscalID {0}
update GL_TransactionDetail set Status = 0 where TransactionID in ( select TransactionID from GL_TransactionHeader where DocumentTypeID = @DocumentTypeID and DocumentDate between @FromDate and @ToDate and CompanyID = @CompanyID and PeriodID = @PeriodID and FiscalID = @FiscalID {1} ) and CompanyID = @CompanyID and PeriodID = @PeriodID
